/** Small 2D no-sliding balance experiment. Not a building-safety simulator. */
export const PIECES=Object.freeze({wide:{label:'넓은 받침',w:1.4,h:1,density:1,color:'#91b5bc'},plank:{label:'긴 널판',w:4.8,h:.45,density:1,color:'#e7bd64'},column:{label:'긴 기둥',w:.75,h:2.2,density:1,color:'#8bb4a0'},cube:{label:'작은 네모',w:1,h:1,density:1,color:'#dca092'},heavy:{label:'묵직한 추',w:1.2,h:.7,density:3,color:'#9b96b8'}});
export const MISSIONS=Object.freeze([
{id:'tower',title:'높이 쌓는 탑',goal:'3개 이상으로 4칸 높이 · 양쪽 6° 시험',height:4,minPieces:3,tilt:6,pads:[[-4.5,4.5]],hint:'넓은 받침 위에 기둥을 쌓아 봐요. 높아질수록 작은 기울임에도 무게중심이 멀리 옮겨 가요.'},
{id:'bridge',title:'골짜기 건너기',goal:'가운데 빈틈을 잇고 추 3을 받쳐요 · 양쪽 4°',tilt:4,pads:[[-4.5,-1.8],[1.8,4.5]],payload:3,hint:'양쪽 둑을 모두 짚는 널판이 필요해요. 가운데 시험 추를 올렸을 때도 받침으로 힘이 전해질까요?'},
{id:'balance',title:'기울지 않는 날개',goal:'받침 밖으로 1칸 이상 뻗기 · 양쪽 3°',tilt:3,pads:[[-4.5,4.5]],overhang:1,hint:'널판이 한쪽으로 길게 나갔다면 반대쪽에 묵직한 추를 놓아 보세요. 추의 질량은 같은 부피의 3배예요.'},
{id:'free',title:'내 마음대로 건축',goal:'최대 10개로 만들어 보고 균형을 시험해요',tilt:6,pads:[[-4.5,4.5]],hint:'다른 모양도 같은 무게중심을 만들 수 있어요. 회전하고 옮기면서 비교해 보세요.'}
]);
export const missionById=id=>MISSIONS.find(m=>m.id===id)??MISSIONS[0];
export const dimensions=b=>{const p=PIECES[b.type];return {w:b.rot?p.h:p.w,h:b.rot?p.w:p.h,mass:p.w*p.h*p.density};};
const edges=b=>{const d=dimensions(b);return {left:b.x-d.w/2,right:b.x+d.w/2,top:b.y+d.h,...d};};
const overlap=(a,b)=>Math.min(a[1],b[1])-Math.max(a[0],b[0]);
export const initialBuild=(mission='tower',blocks=[])=>({mission:missionById(mission).id,blocks:blocks.map(b=>({...b})),history:[],serial:Math.max(0,...blocks.map(b=>Number(b.id.slice(1))||0)),phase:'editing',message:'블록을 끌어 놓거나, 고른 뒤 작업장을 눌러요',testTime:0,result:null});
export function settled(blocks){const placed=[];for(const b of [...blocks].sort((a,b)=>a.y-b.y)){const d=dimensions(b),range=[b.x-d.w/2,b.x+d.w/2];let y=0;for(const other of placed){const e=edges(other);if(overlap(range,[e.left,e.right])>.015)y=Math.max(y,e.top);}placed.push({...b,y});}return placed;}
function history(s,blocks,message){return {...s,blocks,history:[...s.history,s.blocks.map(b=>({...b}))].slice(-25),phase:'editing',testTime:0,result:null,message};}
export function placePiece(s,type,x,rot=false,id=null){if(s.phase==='testing'||typeof type!=='string'||!Object.hasOwn(PIECES,type)||!Number.isFinite(x)||typeof rot!=='boolean'||(!id&&s.blocks.length>=10))return s;const d=dimensions({type,rot}),nx=Math.max(Math.ceil((-4.5+d.w/2)*4)/4,Math.min(Math.floor((4.5-d.w/2)*4)/4,Math.round(x*4)/4));if(nx-d.w/2< -4.51||nx+d.w/2>4.51)return s;const rest=settled(s.blocks.filter(b=>b.id!==id)),b={id:id??'b'+(s.serial+1),type,x:nx,y:0,rot};for(const other of rest){const e=edges(other);if(overlap([nx-d.w/2,nx+d.w/2],[e.left,e.right])>.015)b.y=Math.max(b.y,e.top);}if(b.y+d.h>7)return {...s,message:'작업장은 높이 7칸까지예요. 옆에 놓거나 낮은 블록을 골라요'};return {...history(s,[...rest,b],`${PIECES[type].label}을 놓았어요. 시험하며 균형을 확인해요`),serial:id?s.serial:s.serial+1};}
export function contactIntervals(blocks,mission){const contacts=[];for(const top of blocks){const a=edges(top);if(Math.abs(top.y)<.001){for(const pad of mission.pads){const lo=Math.max(a.left,pad[0]),hi=Math.min(a.right,pad[1]);if(hi-lo>.015)contacts.push({upper:top.id,lower:null,lo,hi,y:0});}}for(const lower of blocks){if(lower.id===top.id)continue;const b=edges(lower);if(Math.abs(top.y-b.top)<.001){const lo=Math.max(a.left,b.left),hi=Math.min(a.right,b.right);if(hi-lo>.015)contacts.push({upper:top.id,lower:lower.id,lo,hi,y:top.y});}}}return contacts;}
/** Deterministic active-set nonnegative least squares: force and moment balance. */
export function solveReactions(columns,rhs){const m=columns.length,n=rhs.length,x=Array(m).fill(0),passive=new Set(),dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0),norm=columns.map(c=>dot(c,c)),tol=1e-9;let iterations=0,innerExhausted=false;
 const residual=()=>rhs.map((b,i)=>b-columns.reduce((v,c,j)=>v+c[i]*x[j],0));
 function leastSquares(ids){const a=ids.map((j,r)=>ids.map((k,c)=>dot(columns[j],columns[k])+(r===c?1e-11:0))),b=ids.map(j=>dot(columns[j],rhs)),len=ids.length;for(let i=0;i<len;i++){let p=i;for(let k=i+1;k<len;k++)if(Math.abs(a[k][i])>Math.abs(a[p][i]))p=k;[a[p],a[i]]=[a[i],a[p]];[b[p],b[i]]=[b[i],b[p]];const v=a[i][i];if(Math.abs(v)<1e-14)continue;for(let k=i+1;k<len;k++){const f=a[k][i]/v;for(let j=i;j<len;j++)a[k][j]-=f*a[i][j];b[k]-=f*b[i];}}const out=Array(len).fill(0);for(let i=len-1;i>=0;i--){let v=b[i];for(let j=i+1;j<len;j++)v-=a[i][j]*out[j];out[i]=Math.abs(a[i][i])<1e-14?0:v/a[i][i];}return out;}
 while(iterations++<800){const r=residual(),w=columns.map(c=>dot(c,r));let j=-1,max=tol;for(let i=0;i<m;i++)if(!passive.has(i)&&norm[i]>tol&&w[i]>max){max=w[i];j=i;}if(j<0)break;passive.add(j);let inner=0;while(inner++<120){const ids=[...passive],z=Array(m).fill(0),solution=leastSquares(ids);ids.forEach((id,i)=>z[id]=solution[i]);if(ids.every(id=>z[id]>tol)){for(let i=0;i<m;i++)x[i]=z[i];break;}let alpha=1;for(const id of ids)if(z[id]<=tol)alpha=Math.min(alpha,x[id]/(x[id]-z[id]||1));for(let i=0;i<m;i++)x[i]+=alpha*(z[i]-x[i]);for(const id of ids)if(x[id]<=tol){x[id]=0;passive.delete(id);}if(!passive.size)break;}if(inner>120)innerExhausted=true;}
 const r=residual(),gradient=columns.map(c=>dot(c,r)),finite=[...x,...r].every(Number.isFinite),kkt=finite&&x.every((v,i)=>v>=-1e-8&&(v>1e-8?Math.abs(gradient[i])<1e-7:gradient[i]<1e-7));return {forces:x,residual:r,error:finite?Math.sqrt(dot(r,r)):Infinity,iterations,converged:iterations<=800&&!innerExhausted&&kkt};}
export function analyzeBuild(blocks,mission,angle=0,{payload=true,margin=.025}={}){
 const contacts=contactIntervals(blocks,mission),mass=blocks.reduce((n,b)=>n+dimensions(b).mass,0),center=mass?{x:blocks.reduce((n,b)=>n+b.x*dimensions(b).mass,0)/mass,y:blocks.reduce((n,b)=>n+(b.y+dimensions(b).h/2)*dimensions(b).mass,0)/mass}:{x:0,y:0};const tilt=Math.tan(angle*Math.PI/180),project=(x,y)=>x-y*tilt,columns=[],mapping=[],rhs=Array(blocks.length*2).fill(0),ids=blocks.map(b=>b.id),loadBlock=mission.payload&&payload?[...blocks].filter(b=>{const e=edges(b);return e.left<=0&&e.right>=0;}).sort((a,b)=>edges(b).top-edges(a).top)[0]:null;const total=Math.max(1,mass+(loadBlock?mission.payload:0));
 for(const[i,b]of blocks.entries()){const d=dimensions(b);rhs[i*2]=d.mass/total;if(b===loadBlock){rhs[i*2]+=mission.payload/total;rhs[i*2+1]=(project(0,edges(b).top+.25)-project(b.x,b.y+d.h/2))*mission.payload/total/5;}}
 for(const c of contacts){const shrink=Math.min(margin,(c.hi-c.lo)/4);for(const px of [c.lo+shrink,c.hi-shrink]){const column=Array(rhs.length).fill(0);for(const[id,sign]of[[c.upper,1],[c.lower,-1]]){if(!id)continue;const i=ids.indexOf(id),b=blocks[i],d=dimensions(b);column[i*2]=sign;column[i*2+1]=sign*(project(px,c.y)-project(b.x,b.y+d.h/2))/5;}columns.push(column);mapping.push({...c,x:px});}}
 const solved=solveReactions(columns,rhs),stable=blocks.length>0&&solved.error<1e-6;let worst=-1,error=0;solved.residual.forEach((r,i)=>{if(Math.abs(r)>error){error=Math.abs(r);worst=Math.floor(i/2);}});const failed=blocks[worst]?.id??null;const unsupported=blocks.find(b=>!contacts.some(c=>c.upper===b.id));let hint=unsupported?.id??null;if(!stable&&solved.converged&&!unsupported){for(const block of [...blocks].sort((a,b)=>a.y-b.y)){const row=ids.indexOf(block.id)*2+1,relaxed=solveReactions(columns.map(c=>c.map((v,i)=>i===row?0:v)),rhs.map((v,i)=>i===row?0:v));if(relaxed.error<1e-6){hint=block.id;break;}}}return {stable,inconclusive:!stable&&!solved.converged,angle,center,mass,contacts,forces:solved.forces.map((force,i)=>({...mapping[i],force:force*total})),error:solved.error,failedId:hint,payload:loadBlock?{mass:mission.payload,x:0,y:edges(loadBlock).top+.25}:null,message:!stable&&!solved.converged?'균형 계산을 마치지 못했어요. 블록을 조금 옮기거나 다시 시험해 주세요':stable?'무게가 받침으로 전달돼 균형을 잡았어요':unsupported?'받쳐 주는 면이 없는 블록이 있어요':'무게가 받침 밖으로 쏠려요. 받침을 넓히거나 반대쪽에 무게를 옮겨 보세요'};
}
export function evaluateBuild(s){const m=missionById(s.mission),checks=[0,m.tilt,-m.tilt].map(a=>analyzeBuild(s.blocks,m,a)),failure=checks.find(r=>!r.stable),height=Math.max(0,...s.blocks.map(b=>edges(b).top));let goal=true,why='양쪽 기울임까지 통과했어요';if(m.height&&(height<m.height||s.blocks.length<m.minPieces)){goal=false;why=`블록 ${m.minPieces}개 이상으로 높이 ${m.height}칸에 도전해요`;}if(m.payload){const touchingBoth=s.blocks.some(b=>{const contacts=contactIntervals(s.blocks,m).filter(c=>c.upper===b.id);return contacts.some(c=>c.lo< -1.8)&&contacts.some(c=>c.hi>1.8);});if(!touchingBoth){goal=false;why='가운데 빈틈을 이어 양쪽에서 받쳐 주세요';}}if(m.overhang){const contacts=contactIntervals(s.blocks,m),found=s.blocks.some(b=>{if(b.y<=.001)return false;const c=contacts.filter(c=>c.upper===b.id);if(!c.length)return false;const e=edges(b),lo=Math.min(...c.map(c=>c.lo)),hi=Math.max(...c.map(c=>c.hi));return Math.max(lo-e.left,e.right-hi)>=m.overhang;});if(!found){goal=false;why='위쪽 블록을 받침 밖으로 1칸 이상 뻗어 보세요';}}return {complete:!failure&&goal,stable:!failure,checks,failure,height,message:failure?failure.message:why};}
export function reduceBuild(s,a){if(a.type==='UNDO'&&s.phase!=='testing'&&s.history.length)return {...s,blocks:s.history.at(-1).map(b=>({...b})),history:s.history.slice(0,-1),phase:'editing',result:null,message:'한 번 전의 쌓기로 돌아왔어요'};if(a.type==='CLEAR'&&s.phase!=='testing')return history(s,[],'다시 마음껏 쌓아 봐요');if(a.type==='REMOVE'&&s.phase!=='testing'&&s.blocks.some(b=>b.id===a.id))return history(s,settled(s.blocks.filter(b=>b.id!==a.id)),'고른 블록을 빼고 위쪽 블록을 내려놓았어요');if(a.type==='TEST'&&s.blocks.length&&s.phase!=='testing')return {...s,phase:'testing',testTime:0,result:evaluateBuild(s),message:'왼쪽과 오른쪽으로 기울여 보는 중…'};if(a.type==='TICK'&&s.phase==='testing'&&Number.isFinite(a.dt)&&a.dt>0){const testTime=Math.min(3.6,s.testTime+Math.min(.1,a.dt));return {...s,testTime,phase:testTime>=3.6?(s.result.complete?'complete':'failed'):'testing',message:testTime>=3.6?s.result.message:s.message};}if(a.type==='EDIT'||a.type==='CANCEL')return {...s,phase:'editing',testTime:0,result:null,message:'블록을 옮겨 다른 균형을 찾아봐요'};return s;}
export const initialBuildSave=()=>({schemaVersion:1,selected:'tower',completed:[],builds:{}});
export function validateBuildSave(raw){if(raw===undefined)return initialBuildSave();if(!raw||raw.schemaVersion!==1||!MISSIONS.some(m=>m.id===raw.selected)||!Array.isArray(raw.completed)||new Set(raw.completed).size!==raw.completed.length||raw.completed.some(id=>!MISSIONS.some(m=>m.id===id))||!raw.builds||typeof raw.builds!=='object'||Array.isArray(raw.builds))return null;const builds={};for(const[id,list]of Object.entries(raw.builds)){if(!MISSIONS.some(m=>m.id===id)||!Array.isArray(list)||list.length>10)return null;const clean=[];for(const b of list){if(!b||typeof b.id!=='string'||!/^b\d{1,6}$/.test(b.id)||clean.some(c=>c.id===b.id)||typeof b.type!=='string'||!Object.hasOwn(PIECES,b.type)||typeof b.rot!=='boolean'||!Number.isFinite(b.x)||!Number.isFinite(b.y))return null;const e=edges(b);if(b.y<0||e.top>7.001||e.left< -4.51||e.right>4.51)return null;if(clean.some(c=>{const f=edges(c);return overlap([e.left,e.right],[f.left,f.right])>.01&&overlap([b.y,e.top],[c.y,f.top])>.01;}))return null;clean.push({id:b.id,type:b.type,x:b.x,y:b.y,rot:b.rot});}builds[id]=clean;}return {schemaVersion:1,selected:raw.selected,completed:[...raw.completed],builds};}
